package com.jobpilot.application;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController @RequestMapping("/applications")public class ApplicationController{private final ApplicationService service;public ApplicationController(ApplicationService s){service=s;}@GetMapping List<ApplicationDtos.View>list(){return service.list();}@PostMapping @ResponseStatus(HttpStatus.CREATED)ApplicationDtos.View create(@Valid @RequestBody ApplicationDtos.CreateApplication d){return service.create(d);}@PatchMapping("/{id}")ApplicationDtos.View update(@PathVariable Long id,@Valid @RequestBody ApplicationDtos.UpdateApplication d){return service.update(id,d);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable Long id){service.delete(id);}}
